import { formatEuros } from './money.js';
import { lineTotal, invoiceTotals } from './invoices.js';
import { roundCents } from './money.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, issueDate: string, status: string, lines: Array, dueDate?: string, voucher?: { code: string, amount: number }, payments?: Array }} invoice
 * @param {string} customerName
 * @returns {string}
 */
export function renderInvoiceText(invoice, customerName) {
  const lines = [];

  // First line: invoice number or DRAFT
  lines.push(invoice.number ?? 'DRAFT');

  // Second line: customer name
  lines.push(customerName);

  // Invoice lines
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const unitPriceFormatted = formatEuros(line.unitPrice);
    const totalFormatted = formatEuros(total);
    let lineText = `${line.qty} × ${line.name} @ ${unitPriceFormatted} = ${totalFormatted}`;

    // Add discount if present
    if (line.discountPercent) {
      const discount = roundCents(total * line.discountPercent / 100);
      const discountFormatted = formatEuros(discount);
      lineText += ` (−${discountFormatted} @ ${line.discountPercent}%)`;
    }

    lines.push(lineText);
  }

  // Totals
  const totals = invoiceTotals(invoice);
  if (totals.discount > 0) {
    const discountFormatted = formatEuros(totals.discount);
    lines.push(`Discount: −${discountFormatted}`);
  }

  if (totals.vat > 0) {
    const vatFormatted = formatEuros(totals.vat);
    lines.push(`VAT: +${vatFormatted}`);
  }

  // Voucher (if any) before total
  if (invoice.voucher && invoice.voucher.amount > 0) {
    const voucherFormatted = formatEuros(invoice.voucher.amount);
    lines.push(`Voucher: −${voucherFormatted}`);
  }

  const totalFormatted = formatEuros(totals.total);
  lines.push(`Total: ${totalFormatted}`);

  // Due date (if present)
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Paid amount (if invoice has payments)
  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, payment) => sum + payment.amount, 0);
    const paidFormatted = formatEuros(totalPaid);
    lines.push(`Paid: ${paidFormatted}`);
  }

  return lines.join('\n');
}

