  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 1, unitPrice: 9500, vatRate: 21, discountPercent: 150 }],
  };

  const text = renderInvoiceText(invoice, 'Northwind Studio');
  const lines = text.split('\n');

  // Line: 1 × €95.00 = €95.00 with 150% discount = €142.50
  // Discount shown: €142.50
  // Total clamped at 0
  assert.equal(lines[2], '1 × Development (hour) @ €95.00 = €95.00 (−€142.50 @ 150%)');
  assert.equal(lines[3], 'Discount: −€142.50');
  assert.equal(lines[4], 'Total: €0.00');
});

test('renderInvoiceText: shows VAT on separate line', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002', // Blue Fern Bakery, standard tier, 0% discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const text = renderInvoiceText(invoiceResult.value, 'Test Customer');
  const lines = text.split('\n');

  // DEV-HOUR: 10 × €95.00 = €950.00
  // Bulk discount (qty >= 10): 2.5% of €950.00 = €23.75
  // VAT (21% of €926.25): €194.51
  // Total: €1,120.76
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Test Customer');
  assert.equal(lines[2], '10 × Development (hour) @ €95.00 = €950.00');
  assert.equal(lines[3], 'Discount: −€23.75');
  assert.equal(lines[4], 'VAT: +€194.51');
  assert.equal(lines[5], 'Total: €1,120.76');
});

test('renderInvoiceText: does not show VAT line if VAT is 0', () => {
